def monotonic(l: list) -> bool:
    if not l:
        return True
    increasing = decreasing = None
    for i in range(1, len(l)):
        if l[i-1] < l[i]:
            increasing = None
        if l[i-1] > l[i]:
            decreasing = None
        if increasing is None:
            increasing = True
        if decreasing is None:
            decreasing = True
        if increasing is False and decreasing is False:
            return False
    return True
